style.css:
@-moz-document domain("ducs.google.com") {
* {
		font-family: "Arial Rounded MT Bold", Arial, Helvetica, sans-serif;
	}
	body,
    div#docs-editor-container,
    .docs-body-pageless .navigation-widget-floating-navigation-button.navigation-widget,
    .kix-appview-editor,
    body[class],
    [id=docs-chrome],
	[id=docs-editor],
	[id=docs-header],
	[id=docs-bars],
	[id=docs-titlebar],
	[id=docs-toolbar-wrapper],
	[id=docs-primary-toolbars],
	[id=docs-side-toolbar],
	.left-sidebar-container-content, 
	body.docs-body-pageless,
	body.docs-hub,
    .kix-rotatingtilemanager,
    .kix-rotatingtilemanager.docs-ui-hit-region-surface, 
    [id=docs-editor-container] {
		background: #000000 !important;
		color: #ffcc99 !important;
	}
    .kix-appview-editor, 
    .docs-body-pageless .navigation-widget-floating-navigation-button.navigation-widget, 
	.docs-titlebar-buttons {
		background: #000000 !important;
	}
    .docs-gm .docs-menubar .goog-control, 
	.jfk-button-standard,
    div.docs-grille-gm3 .docs-title-input,
    .docs-title-input,
    .docs-title-input:focus, 
    input.docs-title-input,
    input.docs-title-input:focus 
    {
		color: #ffcc99 !important;
	}
    .assisted-actions, 
    .goog-toolbar-button,
    .goog-toolbar-combo-button, 
    .goog-toolbar-select, 
    .goog-toolbar-menu-button, 
    .kix-appview, 
    div.kix-appview-editor, 
    .kix-appview-editor-container, 
    #kix-horizontal-ruler-container, 
    .kix-rotatingtilemanager.docs-ui-hit-region-surface,
    .docs-body-pageless #kix-horizontal-ruler-container.docs-ruler .docs-horizontal-ruler, 
    .docs-body-pageless #kix-horizontal-ruler-container.docs-ruler .docs-ruler-background-inner, 
    .docs-body-pageless .docs-vertical-ruler {
      filter: invert(1);
    }
}
